package com.careerguidance.security;
import com.careerguidance.entity.AccountStatus; import com.careerguidance.repository.UserRepository; import org.springframework.security.authorization.*; import org.springframework.security.core.*; import org.springframework.security.web.access.intercept.RequestAuthorizationContext; import org.springframework.stereotype.Component; import java.util.function.Supplier;
@Component public class VerifiedMentorAuthorizationManager implements AuthorizationManager<RequestAuthorizationContext> { private final UserRepository users; public VerifiedMentorAuthorizationManager(UserRepository u){users=u;} public AuthorizationDecision check(Supplier<Authentication> auth,RequestAuthorizationContext ignored){Authentication a=auth.get();boolean role=a!=null&&a.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_MENTOR"));boolean verified=role&&users.findByEmail(a.getName()).map(u->u.getAccountStatus()==AccountStatus.VERIFIED).orElse(false);return new AuthorizationDecision(verified);} }
